  3	public final class BucketSortTest {
  4	
  5	    private BucketSortTest() {
  6	    }
  7	
  8	    public static void main(String[] args) {
  9	        sortsValuesInPlace();
 10	        returnsSortedCopyWithoutMutatingInput();
 11	        returnsDistinctArrayForSortedCopy();
 12	        sortsDuplicateValues();
 13	        sortsValuesAtLowerBound();
 14	        sortsSingleValue();
 15	        sortsValuesNearUpperBound();
 16	        rejectsUnsupportedValues();
 17	        rejectsNullInput();
 18	        handlesEmptyInput();
 19	        returnsEmptySortedCopy();
 20	    }
 21	
 22	    private static void sortsValuesInPlace() {
 23	        assertSortsInPlace(
 24	            new float[]{0.42f, 0.32f, 0.23f, 0.52f, 0.25f, 0.47f},
 25	            new float[]{0.23f, 0.25f, 0.32f, 0.42f, 0.47f, 0.52f},
 26	            "sort should order values in place"
 27	        );
 28	    }
 29	
 30	    private static void returnsSortedCopyWithoutMutatingInput() {
 31	        assertSortedCopy(
 32	            new float[]{0.78f, 0.17f, 0.39f},
 33	            new float[]{0.17f, 0.39f, 0.78f},
 34	            "sortedCopy should not mutate the source array"
 35	        );
 36	    }
 37	
 38	    private static void returnsDistinctArrayForSortedCopy() {
 39	        float[] original = {0.31f, 0.21f};
 40	        float[] copy = BucketSort.sortedCopy(original);
 41	
 42	        if (copy == original) {
 43	            throw new AssertionError("sortedCopy should return a distinct array instance");
 44	        }
 45	    }
 46	
 47	    private static void sortsDuplicateValues() {
 48	        assertSortsInPlace(
 49	            new float[]{0.41f, 0.12f, 0.41f, 0.12f, 0.73f},
 50	            new float[]{0.12f, 0.12f, 0.41f, 0.41f, 0.73f},
 51	            "sort should handle duplicate values"
 52	        );
 53	    }
 54	
 55	    private static void sortsValuesAtLowerBound() {
 56	        assertSortsInPlace(
 57	            new float[]{0.25f, 0.0f, 0.75f},
 58	            new float[]{0.0f, 0.25f, 0.75f},
 59	            "sort should support the lower bound"
 60	        );
 61	    }
 62	
 63	    private static void sortsSingleValue() {
 64	        assertSortsInPlace(
 65	            new float[]{0.4f},
 66	            new float[]{0.4f},
 67	            "sort should handle a single value"
 68	        );
 69	    }
 70	
 71	    private static void sortsValuesNearUpperBound() {
 72	        assertSortsInPlace(
 73	            new float[]{0.9999f, 0.0001f, 0.5f},
 74	            new float[]{0.0001f, 0.5f, 0.9999f},
 75	            "sort should support values close to the upper bound"
 76	        );
 77	    }
 78	
 79	    private static void rejectsUnsupportedValues() {
 80	        assertRejectsUnsupportedValue(1.0f, "sort should reject values outside [0.0, 1.0)");
 81	        assertRejectsUnsupportedValue(-0.01f, "sort should reject negative values");
 82	        assertRejectsUnsupportedValue(Float.NaN, "sort should reject NaN");
 83	        assertRejectsUnsupportedValue(Float.POSITIVE_INFINITY, "sort should reject infinity");
 84	    }
 85	
 86	    private static void rejectsNullInput() {
 87	        assertThrows(
 88	            NullPointerException.class,
 89	            () -> BucketSort.sort(null),
 90	            "sort should reject null input"
 91	        );
 92	    }
 93	
 94	    private static void handlesEmptyInput() {
 95	        float[] values = {};
 96	        BucketSort.sort(values);
 97	        assertArrayEquals(new float[]{}, values, "sort should leave empty input unchanged");
 98	    }
 99	
100	    private static void returnsEmptySortedCopy() {
101	        float[] copy = BucketSort.sortedCopy(new float[]{});
102	        assertArrayEquals(new float[]{}, copy, "sortedCopy should handle empty input");
103	    }
104	
105	    private static void assertSortsInPlace(float[] input, float[] expected, String message) {
106	        BucketSort.sort(input);
107	        assertArrayEquals(expected, input, message);
108	    }
109	
110	    private static void assertSortedCopy(float[] input, float[] expected, String message) {
111	        float[] original = Arrays.copyOf(input, input.length);
112	        float[] copy = BucketSort.sortedCopy(input);
113	
114	        assertArrayEquals(original, input, message);
115	        assertArrayEquals(expected, copy, "sortedCopy should return sorted data");
116	    }
117	
118	    private static void assertRejectsUnsupportedValue(float value, String message) {
119	        assertThrows(
120	            IllegalArgumentException.class,
121	            () -> BucketSort.sort(new float[]{0.5f, value}),
122	            message
123	        );
124	    }
125	
126	    private static void assertArrayEquals(float[] expected, float[] actual, String message) {
127	        if (!Arrays.equals(expected, actual)) {
128	            throw new AssertionError(
129	                message
130	                    + ". Expected "
131	                    + Arrays.toString(expected)
132	                    + " but was "
133	                    + Arrays.toString(actual)
134	            );
135	        }
136	    }
137	
138	    private static void assertThrows(
139	        Class<? extends Throwable> expectedType,
140	        ThrowingRunnable runnable,
141	        String message
142	    ) {
143	        try {
144	            runnable.run();
145	        } catch (Throwable error) {
146	            if (expectedType.isInstance(error)) {
147	                return;
148	            }
149	            throw new AssertionError(
150	                message + ". Expected " + expectedType.getSimpleName() + " but caught " + error,
151	                error
152	            );
153	        }
154	
155	        throw new AssertionError(
156	            message + ". Expected " + expectedType.getSimpleName() + " but nothing was thrown"
157	        );
158	    }
159	
160	    @FunctionalInterface
161	    private interface ThrowingRunnable {
162	        void run();
163	    }
164	}
